1: rules_version = '2';
2: 
3: 
4: service cloud.firestore {
5:   match /databases/{database}/documents {
6:     function changed() {
7:       return request.resource.data.diff(resource.data).affectedKeys();
8:     }
9: 
10:     match /drivers/{driverId} {
11:       allow read: if true;
12:       allow create: if request.resource.data.approvalStatus == 'pending'
13:                     && request.resource.data.balance == 0;
14:       // El saldo solo baja desde la app: el cobro en efectivo descuenta la
15:       // comisión. Lo que lo sube (un pago con Mercado Pago) lo escribe el
16:       // backend con firebase-admin, que no pasa por estas reglas.
17:       allow update: if !changed().hasAny(['approvalStatus', 'createdAt'])
18:                     && (!changed().hasAny(['balance'])
19:                         || request.resource.data.balance < resource.data.balance);
20:       allow delete: if false;
21:     }
22: 
23:     match /trips/{tripId} {
24:       allow read: if true;
25:       allow create: if request.resource.data.status == 'requested'
26:                     && request.resource.data.paymentStatus == null;
27:       allow update: if !changed().hasAny(['paymentId', 'preferenceId', 'driverId'])
28:                     && (!changed().hasAny(['paymentStatus'])
29:                         || request.resource.data.paymentStatus == 'cash')
30:                     && (!changed().hasAny(['status'])
31:                         || request.resource.data.status != 'paid'
32:                         || request.resource.data.paymentStatus == 'cash');
33:       allow delete: if false;
34:     }
35:   }
36: }

